"""AR-300c-3 (derived copy) -- the registry's ability fields are regenerated by a
pre-commit TRANSFORM hook, never by the build.

User decision (BrainCandy, 2026-10-09): the build compiles prompts from the
frontmatter declarations and REPORTS a disagreeing registry copy without
refusing and without writing the package source tree (that half is pinned by
test_ar_300c_3_derived_copy_comparison.py's build test). The copy is
regenerated by a new transform hook, modelled on ``transform-doc-index``.

ASSUMED PRODUCTION CONTRACT (the ACs do not name it; python-coder builds to it):
  * hook id ``transform-agent-registry`` in
    ``templates/scripts/commit_guardian/commit_guardian.json``, a sibling of
    ``transform-doc-index`` (tier ``transform``, language ``system``, stage
    ``pre-commit``, ``pass_filenames: false``, same ``change_set_source``,
    ``entry`` identical to the doc-index one with the script name swapped);
    ``files`` regex matches ``templates/agents/*.md`` and
    ``config/agent_registry.json``.
  * script ``templates/scripts/commit_guardian/transform_agent_registry.py``
    (deployed to ``<output_root>/scripts/commit_guardian/``). Run with
    ``--package-root DIR`` it rewrites ``DIR/config/agent_registry.json``'s
    ability field (``skills_invoked`` only; the retired ``skills_used`` is dropped) from the templates'
    ``skills:`` declarations, touches NOTHING else, does no git staging, and
    exits 0. Without the flag it works on the git toplevel and re-stages the
    registry when it changed (like transform_doc_index.py).

RED BASELINE: the script and the manifest entry do not exist.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path


sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from _ar_300c_support import (  # noqa: E402
    GRANT_KEY,
    REPO_ROOT,
    copy_package_slice,
    declared_entries,
    descriptive_only_ids,
    granted_ids,
    installed_skill_ids,
    registry_agents,
    strip_frontmatter_keys,
    template_frontmatter,
    template_stem,
    transform_or_fail,
)
from _ar_300e_support import MACRO, yaml_block  # noqa: E402

HOOK_DIR = REPO_ROOT / "templates" / "scripts" / "commit_guardian"
HOOK_SCRIPT = HOOK_DIR / "transform_agent_registry.py"
MANIFEST = HOOK_DIR / "commit_guardian.json"
_COMPARE_KINDS = {"divergent", "declaration-only", "record-only"}


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------

def _run_hook(script: Path, pkg: Path) -> subprocess.CompletedProcess:
    return subprocess.run([sys.executable, str(script), "--package-root", str(pkg)],
                          capture_output=True, text=True, timeout=120, check=False)


def _hook_or_fail(script: Path, pkg: Path) -> None:
    assert script.is_file(), f"transform hook script not found: {script}"
    proc = _run_hook(script, pkg)
    assert proc.returncode == 0, f"transform hook exited {proc.returncode}: {proc.stderr[-600:]}"


def _remove_item(text: str, skill_id: str) -> str:
    """Drop one ``- skill_id: X`` item (and its indented continuation lines)."""
    lines, out, skipping = text.split("\n"), [], False
    for line in lines:
        if line.strip() == f"- skill_id: {skill_id}":
            skipping = True
            continue
        if skipping and line.startswith("  "):
            continue
        skipping = False
        out.append(line)
    return "\n".join(out)


def _add_item(text: str, skill_id: str) -> str:
    lines, out = text.split("\n"), []
    for line in lines:
        out.append(line)
        if line == f"{GRANT_KEY}:":
            out.extend([f"- skill_id: {skill_id}", "  mode: always"])
    return "\n".join(out)


SPAWN = "spawn_allowlist"


def _sync_registry_spawn(pkg: Path) -> None:
    """Slice 5 (AR-300c-5-ii widened the hook to regenerate ``spawn_allowlist`` too): make
    the registry's sub-agent lists agree with the templates' declarations BEFORE the state
    these ability tests snapshot, so the skills-only assertions below keep proving exactly
    what they proved (nothing but the ability fields of the EDITED agents changes) instead of
    also absorbing the spawn regeneration, which the spawn tests at the end of this file own.
    Declared list (absent -> []) copied into every templated record, written the one way both
    writers write the registry."""
    path = pkg / "config" / "agent_registry.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    for agent in data["agents"]:
        stem = template_stem(agent)
        if stem and (pkg / "templates" / "agents" / f"{stem}.md").is_file():
            agent[SPAWN] = list(template_frontmatter(pkg / "templates" / "agents" / f"{stem}.md").get(SPAWN) or [])
    path.write_text(json.dumps(data, indent=4, ensure_ascii=False) + "\n", encoding="utf-8")


def _prepared(tmp_path: Path):
    """Package slice -> real hook (registry copy now consistent) -> then CHANGE
    two agents' declarations in frontmatter only. Returns (pkg, edited agent
    ids, registry bytes S1)."""
    pkg = copy_package_slice(tmp_path / "pkg")
    transform_or_fail(pkg)
    _sync_registry_spawn(pkg)
    s1 = (pkg / "config" / "agent_registry.json").read_bytes()
    installed = installed_skill_ids(pkg)
    by_stem = {template_stem(a): a for a in registry_agents(pkg) if template_stem(a)}
    revoked = added = None
    for tpl in sorted((pkg / "templates" / "agents").glob("*.md")):
        agent = by_stem.get(tpl.stem)
        entries = declared_entries(template_frontmatter(tpl))
        ids = [e["skill_id"] for e in entries]
        if agent is None or not ids:
            continue
        if revoked is None and len(ids) >= 2 and ids[-1] not in descriptive_only_ids(agent):
            tpl.write_text(_remove_item(tpl.read_text(encoding="utf-8"), ids[-1]), encoding="utf-8")
            revoked = agent["id"]
        elif added is None:
            extra = sorted(installed - set(ids))[0]
            tpl.write_text(_add_item(tpl.read_text(encoding="utf-8"), extra), encoding="utf-8")
            added = agent["id"]
        if revoked and added:
            break
    assert revoked and added and revoked != added, "could not pick two agents to edit"
    return pkg, {revoked, added}, s1


def _declarations(pkg: Path) -> dict:
    out = {}
    for a in registry_agents(pkg):
        if template_stem(a):
            fm = template_frontmatter(pkg / "templates" / "agents" / f"{template_stem(a)}.md")
            if fm.get(GRANT_KEY):
                out[a["id"]] = declared_entries(fm)
    return out


def _compare_findings(pkg: Path) -> list[dict]:
    from agent_ability_verdict import verify_abilities  # noqa: PLC0415

    verdict = verify_abilities(_declarations(pkg), registry_agents(pkg),
                               packaged_skills_root=pkg / "templates" / "skills",
                               project_root=pkg.parent / "project")
    return [f for f in verdict["findings"] if f["kind"] in _COMPARE_KINDS]


def _without_ability_blocks(text: str) -> str:
    """The registry text with every skills_used / skills_invoked block removed."""
    out, depth = [], 0
    for line in text.split("\n"):
        if depth:
            depth += line.count("[") - line.count("]")
            continue
        s = line.strip()
        if s.startswith('"skills_used":') or s.startswith('"skills_invoked":'):
            depth = line.count("[") - line.count("]")
            continue
        out.append(line)
    return "\n".join(out)


# --------------------------------------------------------------------------
# tests
# --------------------------------------------------------------------------

def test_transform_regenerates_the_ability_fields_so_the_verdict_reports_zero_divergence(tmp_path):
    # covers: AR-300c-3
    # angle: criterion
    """AR-300c-3: after declarations change in frontmatter only, the registry copy
    diverges (control: the verdict reports exactly the edited agents); running
    the transform regenerates it and the verdict then reports zero divergence.
    Red today: the transform does not exist."""
    pkg, edited, _s1 = _prepared(tmp_path)
    before = _compare_findings(pkg)
    assert {f["agent"] for f in before} == edited, before
    _hook_or_fail(HOOK_SCRIPT, pkg)
    assert _compare_findings(pkg) == []
    by_id = {a["id"]: a for a in registry_agents(pkg)}
    for agent_id, entries in _declarations(pkg).items():
        assert granted_ids(by_id[agent_id]) == {e["skill_id"] for e in entries}, agent_id


def test_transform_writes_skills_invoked_only_and_drops_a_stale_skills_used(tmp_path):
    # covers: AR-400e-2
    # angle: discrimination
    """AR-400e-2 (retargeted from the AR-300c-3 two-field expectation): the hook writes ONLY
    ``skills_invoked`` -- a record that still carries the retired ``skills_used`` (planted
    here, even empty) loses it, and no templated record has it afterwards. Control: the same
    run does regenerate ``skills_invoked`` for the edited agents. Wrong version caught: a hook
    that keeps writing (or leaving) the retired field."""
    pkg, edited, _s1 = _prepared(tmp_path)
    reg = pkg / "config" / "agent_registry.json"
    data = json.loads(reg.read_text(encoding="utf-8"))
    for agent in data["agents"]:
        if template_stem(agent):
            agent["skills_used"] = []
    reg.write_text(json.dumps(data, indent=4) + "\n", encoding="utf-8")
    _hook_or_fail(HOOK_SCRIPT, pkg)
    after = {a["id"]: a for a in registry_agents(pkg)}
    templated = [a for a in after.values() if template_stem(a)]
    assert len(templated) > 30 and not [a["id"] for a in templated if "skills_used" in a]
    assert all(granted_ids(after[i]) == {e["skill_id"] for e in _declarations(pkg)[i]} for i in edited)


def test_transform_changes_no_other_field_and_no_other_agents_record(tmp_path):
    # covers: AR-300c-3
    # angle: boundary
    """AR-300c-3: byte-level -- everything in config/agent_registry.json outside
    the ability fields is identical before and after, and every agent whose
    declaration did not change keeps an identical record. The ability fields DID
    change for the edited agents (control), so this is not 'nothing ran'."""
    pkg, edited, s1 = _prepared(tmp_path)
    _hook_or_fail(HOOK_SCRIPT, pkg)
    s2 = (pkg / "config" / "agent_registry.json").read_bytes()
    assert s2 != s1, "transform changed nothing although declarations changed"
    assert _without_ability_blocks(s2.decode("utf-8")) == _without_ability_blocks(s1.decode("utf-8"))
    before = {a["id"]: a for a in json.loads(s1)["agents"]}
    after_doc = json.loads(s2)
    after = {a["id"]: a for a in after_doc["agents"]}
    assert set(before) == set(after)
    others = [i for i in before if i not in edited]
    assert len(others) > 30
    for agent_id in others:
        assert after[agent_id] == before[agent_id], f"{agent_id}: record changed"
    for agent_id in edited:
        non_ability = lambda r: {k: v for k, v in r.items() if k not in ("skills_used", "skills_invoked")}  # noqa: E731
        assert non_ability(after[agent_id]) == non_ability(before[agent_id]), agent_id
    assert {k: v for k, v in after_doc.items() if k != "agents"} == \
        {k: v for k, v in json.loads(s1).items() if k != "agents"}


def test_transform_is_byte_stable_on_a_second_run(tmp_path):
    # covers: AR-300c-3
    # angle: real_artifact
    """AR-300c-3: a second transform run over the already-regenerated registry
    leaves it byte-identical (and the first run really changed it)."""
    pkg, _edited, s1 = _prepared(tmp_path)
    reg = pkg / "config" / "agent_registry.json"
    _hook_or_fail(HOOK_SCRIPT, pkg)
    first = reg.read_bytes()
    assert first != s1
    _hook_or_fail(HOOK_SCRIPT, pkg)
    assert reg.read_bytes() == first


def _walk_hooks(node):
    if isinstance(node, dict):
        if "id" in node and "entry" in node:
            yield node
        for v in node.values():
            yield from _walk_hooks(v)
    elif isinstance(node, list):
        for v in node:
            yield from _walk_hooks(v)


def test_transform_is_registered_as_a_pre_commit_hook_like_transform_doc_index():
    # covers: AR-300c-3
    # angle: reachability
    """AR-300c-3: the hook is registered in the commit-guardian manifest the way
    transform-doc-index is (read from the real manifest, mirrored field by
    field), its script exists beside the other hook scripts, and its ``files``
    pattern fires for template and registry changes but not for unrelated docs."""
    hooks = {h["id"]: h for h in _walk_hooks(json.loads(MANIFEST.read_text(encoding="utf-8")))}
    doc, mine = hooks["transform-doc-index"], hooks.get("transform-agent-registry")
    assert mine is not None, "transform-agent-registry is not registered in commit_guardian.json"
    assert mine["tier"] == doc["tier"] == "transform"
    for key in ("language", "stages", "pass_filenames", "change_set_source"):
        assert mine[key] == doc[key], key
    assert mine["entry"] == doc["entry"].replace("transform_doc_index.py", "transform_agent_registry.py")
    assert HOOK_SCRIPT.is_file()
    pattern = re.compile(mine["files"])
    assert pattern.search("templates/agents/python-coder.md")
    assert pattern.search("config/agent_registry.json")
    assert not pattern.search("docs/INDEX.md")


# --------------------------------------------------------------------------
# AR-300c-5-ii (slice 5): the same hook also regenerates ``spawn_allowlist``
# --------------------------------------------------------------------------

def _plant(pkg: Path, plan: dict) -> None:
    """Strip every ``spawn_allowlist`` key from the copied templates (text level), then
    insert the planned declarations (``{stem: list}``, real serializer) before the closing
    ``---``. Nothing else in any template changes."""
    for tpl in sorted((pkg / "templates" / "agents").glob("*.md")):
        text, _n = strip_frontmatter_keys(tpl.read_text(encoding="utf-8"), (SPAWN,))
        lines = text.split("\n")
        if tpl.stem in plan and lines[0] == "---":
            close = lines.index("---", 1)
            lines[close:close] = yaml_block(SPAWN, plan[tpl.stem]).split("\n")
        tpl.write_text("\n".join(lines), encoding="utf-8")


def _records(pkg: Path) -> dict:
    return {a["id"]: a for a in registry_agents(pkg)}


def _prepared_spawn(tmp_path: Path):
    """Package slice -> real hook -> every spawn declaration replaced by a PLANNED
    one: a revocation (one fewer than the record), an addition (record empty), the macro
    verbatim, an explicit empty, and agents that keep a registry permission but declare
    nothing. Returns (pkg, roles, registry bytes S1)."""
    pkg = copy_package_slice(tmp_path / "pkg")
    transform_or_fail(pkg)
    recs = [a for a in registry_agents(pkg) if template_stem(a) and a["id"] != "ticket-supervisor"]
    holders = sorted((a for a in recs if a.get(SPAWN)), key=lambda a: a["id"])
    empties = sorted((a["id"] for a in recs if not a.get(SPAWN)))
    revoked = next(a for a in holders if len(a[SPAWN]) >= 2)
    undeclared = next(a for a in holders if a["id"] != revoked["id"])
    roles = {"revoked": revoked["id"], "dropped": revoked[SPAWN][-1], "added": empties[0],
             "explicit_empty": empties[1], "undeclared": undeclared["id"], "macro": "ticket-supervisor"}
    plan = {revoked["id"]: revoked[SPAWN][:-1], empties[0]: ["research-agent"], empties[1]: [],
            "ticket-supervisor": [MACRO, "brainstorm-lead"]}
    _plant(pkg, {template_stem(_records(pkg)[k]): v for k, v in plan.items()})
    return pkg, roles, (pkg / "config" / "agent_registry.json").read_bytes()


def _without_blocks(text: str, names: tuple[str, ...]) -> str:
    """The registry text with every block of the named fields removed (array or ``[]``)."""
    out, depth = [], 0
    for line in text.split("\n"):
        if depth:
            depth += line.count("[") - line.count("]")
            continue
        if any(line.strip().startswith(f'"{n}":') for n in names):
            depth = line.count("[") - line.count("]")
            continue
        out.append(line)
    return "\n".join(out)


def _declared(pkg: Path, agent: dict) -> list:
    return list(template_frontmatter(pkg / "templates" / "agents" / f"{template_stem(agent)}.md").get(SPAWN) or [])


def test_transform_regenerates_spawn_allowlist_and_changes_no_other_byte(tmp_path):
    # covers: AR-300c-5-ii
    # angle: real_artifact
    """AR-300c-5-ii (UPDATE of the AR-300c-3 pinning test): after declarations change in
    frontmatter only, the hook regenerates every templated agent's registry ``spawn_allowlist``
    from its declaration -- a revoked sub-agent leaves, an added one arrives, the ticket-phase
    macro is carried VERBATIM, an explicit empty stays empty and an ABSENT declaration yields
    [] -- and every byte outside skills_used / skills_invoked / spawn_allowlist is unchanged
    (``spawned_by``, ``is_ticket_phase`` and the template-less records included), and a second
    run is byte-stable. Control: before the hook the records DID disagree."""
    pkg, roles, s1 = _prepared_spawn(tmp_path)
    before = _records(pkg)
    assert sorted(before[roles["revoked"]][SPAWN]) != sorted(_declared(pkg, before[roles["revoked"]])), "control"
    reg = pkg / "config" / "agent_registry.json"
    _hook_or_fail(HOOK_SCRIPT, pkg)
    s2 = reg.read_bytes()
    after = _records(pkg)
    examined = 0
    for agent_id, record in after.items():
        if not template_stem(record):
            assert record == before[agent_id], f"{agent_id}: a template-less record changed"
            continue
        examined += 1
        assert sorted(record[SPAWN]) == sorted(_declared(pkg, record)), f"{agent_id}: {record[SPAWN]}"
        assert len(record[SPAWN]) == len(set(record[SPAWN]))
    assert examined > 50
    assert roles["dropped"] not in after[roles["revoked"]][SPAWN]
    assert after[roles["added"]][SPAWN] == ["research-agent"] and after[roles["explicit_empty"]][SPAWN] == []
    assert after[roles["undeclared"]][SPAWN] == [] and before[roles["undeclared"]][SPAWN], "absent declaration -> []"
    assert sorted(after["ticket-supervisor"][SPAWN]) == sorted([MACRO, "brainstorm-lead"])
    blocks = ("skills_used", "skills_invoked", SPAWN)
    assert _without_blocks(s2.decode("utf-8"), blocks) == _without_blocks(s1.decode("utf-8"), blocks)
    for agent_id, record in after.items():
        keep = lambda r: {k: v for k, v in r.items() if k not in blocks}  # noqa: E731
        assert keep(record) == keep(before[agent_id]), f"{agent_id}: a field outside the derived ones changed"
    _hook_or_fail(HOOK_SCRIPT, pkg)
    assert reg.read_bytes() == s2, "a second run changed the registry"


def test_spawn_revocation_is_regenerated_for_that_agent_only(tmp_path):
    # covers: AR-300c-5-ii
    # angle: discrimination
    """AR-300c-5-ii / AR-300d-5: with every registry copy consistent with its declaration
    (the hook is a no-op: control), revoking ONE sub-agent from ONE agent's frontmatter and
    running the hook removes it from THAT agent's registry record and nowhere else -- another
    agent holding the same sub-agent keeps it, and the registry diff is exactly that one list.
    Wrong version caught: removing the sub-agent from a shared structure."""
    pkg = copy_package_slice(tmp_path / "pkg")
    transform_or_fail(pkg)
    templated = [a for a in registry_agents(pkg) if template_stem(a)]
    _plant(pkg, {template_stem(a): list(a.get(SPAWN) or []) for a in templated if a.get(SPAWN)})
    reg = pkg / "config" / "agent_registry.json"
    _hook_or_fail(HOOK_SCRIPT, pkg)
    s0 = reg.read_bytes()
    _hook_or_fail(HOOK_SCRIPT, pkg)
    assert reg.read_bytes() == s0, "control: the hook is not stable over consistent declarations"
    holders = [a["id"] for a in registry_agents(pkg) if "research-agent" in (a.get(SPAWN) or []) and template_stem(a)]
    assert len(holders) >= 2, f"need two holders of research-agent, found {holders}"
    victim, bystander = holders[0], holders[1]
    victim_tpl = pkg / "templates" / "agents" / f"{template_stem(_records(pkg)[victim])}.md"
    kept = [s for s in _declared(pkg, _records(pkg)[victim]) if s != "research-agent"]
    _plant(pkg, {template_stem(a): list(a.get(SPAWN) or []) for a in templated if a.get(SPAWN) and a["id"] != victim}
           | {template_stem(_records(pkg)[victim]): kept})
    assert "research-agent" not in _declared(pkg, _records(pkg)[victim]), victim_tpl
    _hook_or_fail(HOOK_SCRIPT, pkg)
    after = _records(pkg)
    assert "research-agent" not in after[victim][SPAWN] and sorted(after[victim][SPAWN]) == sorted(kept)
    assert "research-agent" in after[bystander][SPAWN]
    before = {a["id"]: a for a in json.loads(s0)["agents"]}
    changed = sorted(i for i in after if after[i] != before[i])
    assert changed == [victim], f"the revocation moved other records: {changed}"
